268:
SELECT "minimum_years"
FROM "jobs"
WHERE "salary" = (SELECT MAX(CAST("salary" AS REAL)) FROM "jobs");

288:
SELECT d."certification"
FROM "degrees" d
WHERE LOWER(TRIM(d."job_post")) = LOWER(TRIM('AI Researcher'));

338:
SELECT h."fees"
FROM "house" h
WHERE h."house_price" = (
    SELECT MAX(CAST(h2."house_price" AS NUMERIC(10, 2)))
    FROM "house" h2
);
